const { Client } = require("ssh2");
const net = require("net");
const fs = require("fs");
const path = require("path");
const os = require("os");
const readline = require("readline");
const { execSync, spawn } = require("child_process");

function log(msg) {
  const now = new Date();
  const ts =
    now.toLocaleTimeString("en-GB", { hour12: false }) +
    "." +
    String(now.getMilliseconds()).padStart(3, "0");
  console.log(`[${ts}] ${msg}`);
}

const SSH_USER = "root";
const SSH_PORT = 22;
const REMOTE_PORT = 80;
const DEFAULT_KEY_NAME = "id_urcap";
const SSH_CONFIG_PATH = "/etc/ssh/sshd_config";

/** Returns the path to the dedicated URCap SSH key (~/.ssh/id_urcap). */
function getSSHKeyPath() {
  return path.join(os.homedir(), ".ssh", DEFAULT_KEY_NAME);
}

/** Checks whether both the private and public key files exist on disk. */
function hasSSHKey() {
  const keyPath = getSSHKeyPath();
  return fs.existsSync(keyPath) && fs.existsSync(keyPath + ".pub");
}

/** Reads and returns the private key contents as a UTF-8 string. */
function readSSHKey() {
  const keyPath = getSSHKeyPath();
  return fs.readFileSync(keyPath, "utf8");
}

/** Prompts the user with a visible question and returns their answer. */
function promptUser(question) {
  const rl = readline.createInterface({
    input: process.stdin,
    output: process.stderr,
    terminal: true,
  });
  return new Promise((resolve) => {
    rl.question(question, (answer) => {
      rl.close();
      resolve(answer.trim());
    });
  });
}

/** Prompts for a password without echoing input. Falls back to plain readline if not a TTY. */
function promptPassword(prompt) {
  return new Promise((resolve) => {
    const stdin = process.stdin;

    if (!stdin.isTTY) {
      const rl = readline.createInterface({ input: stdin });
      process.stderr.write(prompt);
      rl.once("line", (line) => {
        rl.close();
        resolve(line);
      });
      return;
    }

    process.stderr.write(prompt);
    const wasRaw = stdin.isRaw;
    stdin.setRawMode(true);
    stdin.resume();

    let password = "";
    const onData = (ch) => {
      const c = ch.toString("utf8");
      if (c === "\n" || c === "\r" || c === "\u0004") {
        stdin.setRawMode(wasRaw);
        stdin.removeListener("data", onData);
        stdin.pause();
        process.stderr.write("\n");
        resolve(password);
      } else if (c === "\u0003") {
        stdin.setRawMode(wasRaw);
        process.exit(1);
      } else if (c === "\u007f" || c === "\b") {
        password = password.slice(0, -1);
      } else {
        password += c;
      }
    };
    stdin.on("data", onData);
  });
}

/** Finds an available ephemeral port on localhost by briefly binding to port 0. */
function findAvailablePort() {
  return new Promise((resolve, reject) => {
    const srv = net.createServer();
    srv.listen(0, "127.0.0.1", () => {
      const port = srv.address().port;
      srv.close(() => resolve(port));
    });
    srv.on("error", reject);
  });
}

/** Executes a command on the remote host via the SSH connection. Rejects on non-zero exit. */
function sshExec(conn, command) {
  return new Promise((resolve, reject) => {
    conn.exec(command, (err, stream) => {
      if (err) return reject(err);
      let output = "";
      stream.on("data", (data) => {
        output += data;
      });
      stream.stderr.on("data", (data) => {
        output += data;
      });
      stream.on("close", (code) => {
        if (code !== 0)
          reject(new Error(`Command failed (${code}): ${command}\n${output}`));
        else resolve(output);
      });
    });
  });
}

/**
 * Opens an SSH tunnel to the robot host.
 *
 * @param {string} host - The robot hostname or IP
 * @returns {Promise<{port: number, close: function}>}
 */
async function openTunnel(host) {
  log(`Setting up SSH tunnel to ${host}...`);

  const localPort = await findAvailablePort();

  const useKey = hasSSHKey();
  let usedPassword = null;

  async function connectWithKey() {
    const conn = new Client();
    log(
      `Using SSH key: ${getSSHKeyPath()} - Remember to keep this safe. Or delete after usage.`,
    );
    await new Promise((resolve, reject) => {
      conn.on("ready", resolve);
      conn.on("error", reject);
      conn.connect({
        host,
        port: SSH_PORT,
        username: SSH_USER,
        privateKey: readSSHKey(),
      });
    });
    return conn;
  }

  async function connectWithPassword() {
    const conn = new Client();
    usedPassword = await promptPassword(`${SSH_USER}@${host} password: `);
    await new Promise((resolve, reject) => {
      conn.on("ready", resolve);
      conn.on("error", reject);
      conn.on(
        "keyboard-interactive",
        (_name, _instructions, _lang, prompts, finish) => {
          finish([usedPassword]);
        },
      );
      conn.connect({
        host,
        port: SSH_PORT,
        username: SSH_USER,
        password: usedPassword,
        tryKeyboard: true,
        authHandler: ["password", "keyboard-interactive"],
      });
    });
    return conn;
  }

  let conn;
  if (useKey) {
    try {
      conn = await connectWithKey();
    } catch (err) {
      log(`Key auth failed: ${err.message}`);
      log("Falling back to password authentication...");
      conn = await connectWithPassword();
    }
  } else {
    conn = await connectWithPassword();
  }

  log(`SSH connection established to ${host}`);

  await sshExec(
    conn,
    `sed -i '/^[#]*AllowTcpForwarding/c\\AllowTcpForwarding yes' ${SSH_CONFIG_PATH}`,
  );
  await sshExec(
    conn,
    `sed -i '/^[#]*PubkeyAuthentication/c\\PubkeyAuthentication yes' ${SSH_CONFIG_PATH}`,
  );
  await sshExec(conn, "systemctl restart ssh");
  log("Enabled AllowTcpForwarding + PubkeyAuthentication on robot");

  // Reconnect after sshd restart with retry
  conn.end();
  const MAX_RETRIES = 3;
  const RETRY_DELAY_MS = 500;
  for (let attempt = 1; attempt <= MAX_RETRIES; attempt++) {
    try {
      await new Promise((r) => setTimeout(r, RETRY_DELAY_MS));
      const reconnConn = new Client();
      if (useKey && !usedPassword) {
        await new Promise((resolve, reject) => {
          reconnConn.on("ready", resolve);
          reconnConn.on("error", reject);
          reconnConn.connect({
            host,
            port: SSH_PORT,
            username: SSH_USER,
            privateKey: readSSHKey(),
          });
        });
      } else {
        await new Promise((resolve, reject) => {
          reconnConn.on("ready", resolve);
          reconnConn.on("error", reject);
          reconnConn.on(
            "keyboard-interactive",
            (_name, _instructions, _lang, prompts, finish) => {
              finish([usedPassword]);
            },
          );
          reconnConn.connect({
            host,
            port: SSH_PORT,
            username: SSH_USER,
            password: usedPassword,
            tryKeyboard: true,
            authHandler: ["password", "keyboard-interactive"],
          });
        });
      }
      conn = reconnConn;
      break;
    } catch (err) {
      if (attempt === MAX_RETRIES) throw err;
      log(`Reconnect attempt ${attempt} failed, retrying...`);
    }
  }

  const server = net.createServer((sock) => {
    conn.forwardOut(
      "127.0.0.1",
      localPort,
      "127.0.0.1",
      REMOTE_PORT,
      (err, stream) => {
        if (err) {
          log(`Tunnel forward error: ${err.message}`);
          sock.end();
          return;
        }
        sock.pipe(stream).pipe(sock);
      },
    );
  });

  await new Promise((resolve, reject) => {
    server.listen(localPort, "127.0.0.1", () => resolve());
    server.on("error", reject);
  });

  log(`SSH tunnel active: localhost:${localPort} -> ${host}:${REMOTE_PORT}`);

  const close = async () => {
    try {
      await sshExec(
        conn,
        `sed -i '/^[#]*AllowTcpForwarding/c\\AllowTcpForwarding no' ${SSH_CONFIG_PATH}`,
      );
      await sshExec(
        conn,
        `sed -i '/^[#]*PubkeyAuthentication/c\\PubkeyAuthentication yes' ${SSH_CONFIG_PATH}`,
      );
      await sshExec(conn, "systemctl restart ssh");
      log("Disabled AllowTcpForwarding on robot");
    } catch (err) {
      log(`Warning: failed to disable AllowTcpForwarding: ${err.message}`);
    } finally {
      await new Promise((resolve) => {
        server.close(() => {
          conn.end();
          resolve();
        });
        server.unref();
      });
    }
  };

  return { port: localPort, close, connection: conn, password: usedPassword };
}

/**
 * Offers to set up SSH key-based auth after a successful password connection.
 * Generates a key pair if needed and runs ssh-copy-id to install it on the robot.
 *
 * @param {string} host - The robot hostname or IP
 * @param {string} password - The password already used for the tunnel connection
 * @returns {Promise<boolean>} - Whether keys were set up
 */
async function offerKeySetup(host, password) {
  if (!password || !process.stdin.isTTY) {
    return false;
  }

  const keyExists = hasSSHKey();

  const prompt = keyExists
    ? `Would you like to install your SSH key on ${host}? (y/n) `
    : `Would you like to set up SSH key-based auth for ${host}? (y/n) `;

  const answer = await promptUser(prompt);

  if (answer.toLowerCase() !== "y") {
    return false;
  }

  const keyPath = getSSHKeyPath();

  if (!keyExists) {
    log("Generating SSH key pair...");
    const sshDir = path.dirname(keyPath);
    if (!fs.existsSync(sshDir)) {
      fs.mkdirSync(sshDir, { mode: 0o700, recursive: true });
    }
    execSync(
      `ssh-keygen -t rsa -b 4096 -m PEM -f "${keyPath}" -N "" -C "urcap-utils"`,
      { stdio: "inherit" },
    );
  }

  log(`Installing SSH key on ${host}...`);
  const copyResult = await new Promise((resolve) => {
    const child = spawn(
      "sshpass",
      [
        "-e",
        "ssh-copy-id",
        "-i",
        keyPath,
        "-o",
        "StrictHostKeyChecking=accept-new",
        "-p",
        String(SSH_PORT),
        `${SSH_USER}@${host}`,
      ],
      { stdio: "inherit", env: { ...process.env, SSHPASS: password } },
    );
    child.on("close", (code) => resolve(code === 0));
    child.on("error", () => {
      log("sshpass/ssh-copy-id not found on this system.");
      resolve(false);
    });
  });

  if (copyResult) {
    log(
      "SSH key successfully installed. Future connections will be passwordless.",
    );
    return true;
  } else {
    log("Failed to install SSH key. You can try manually with ssh-copy-id.");
    return false;
  }
}

module.exports = { openTunnel, offerKeySetup, log };
